// The newer looks of the Upcoming events mystery card (looks 6 and up; looks 1-5 are in HackathonTeaser.jsx and TeaserCards.jsx).
//   6 = Jackpot   7 = Scratch card   8 = Chat   9 = Comic page   10 = Newsroom
//   11 = Crash   12 = Cinema   13 = Sunset   14 = Countdown   15 = Quest
// Each look has its own colours (the words and the detail boxes come from teaserCore.jsx, the pictures from newParts.jsx).
// You do not edit this file: the look is picked by itself (see site/designs.js).
import { Actions } from './teaserCore';
import PosterStage from './PosterStage';
import { CardTitle } from './NameReveal';
import { Clock, Field, Prog } from './TeaserCards';
import { Bomb, BsodScreen, ChatThread, Chest, Clapper, ComicPanel, Reels, ScratchPanel, Sunset, TvScreen } from './newParts';
import { CyberCard } from './Cyber';
import './TeaserCardsNew.css';

const Fields = ({ t }) => t.fields.map((f) => <Field key={f.k} f={f} />);

/* ---------- 6. jackpot: a slot machine ---------- */
function Jackpot({ t }) {
  const { copy } = t;
  return (
    <article className={`tc tc-slot t-${t.type} is-${t.phase}`} aria-label={t.label}>
      <div className="tc-sl-lamps" aria-hidden="true">{Array.from({ length: 30 }, (_, i) => <i key={i} />)}</div>
      <div className="tc-sl-grid">
        <PosterStage kind="card" cap={440}><Reels /></PosterStage>
        <div className="tc-sl-main">
          <span className="tc-sl-flag"><i /> {copy.flag}</span>
          <CardTitle t={t} className="tc-title" />
          <p className="tc-lede">{copy.lede}</p>
          <p className="tc-desc">{copy.desc}</p>
          <Clock t={t} />
          <div className="tc-sl-pay"><Fields t={t} /></div>
          <Prog t={t} />
          <Actions t={t} />
        </div>
      </div>
    </article>
  );
}

